require("Game.Lobby.ShopUI.ShopUIView")

ShopUICtrl = class("ShopUICtrl", PageController)
local this = ShopUICtrl;
local instance;


---构造函数
function ShopUICtrl:ctor()
    ShopUICtrl.super.ctor(self);
    self.name = "ShopUI";
    this.broadcastCtrl = BroadcastCtrl.new();
    self.shopData = {};
end

---单例，方便外界调用
function ShopUICtrl.Instance()
    if instance == nil then
        instance = ShopUICtrl.new();
    end
    return instance;
end

---打开页面，可传任意参数
function ShopUICtrl:OpenPage(tab, callback)
    HttpNetworkManager.GetShopData(function (rawData)
        local data = cjson.decode(rawData);
        if (tonumber(data.code) == NetworkConst.CODE_OK) then
            self.shopData[ShopTab.Daily] = data.dailyShop;
            self.shopData[ShopTab.Recharge] = data.rechargeShop;
            self.shopData[ShopTab.Hot] = data.hotShop;
            self.shopData[ShopTab.Discount] = data.discountShop;

            ShopUIView.Instance():SWitchTab(tab);

            if (callback ~= nil) then
                callback();
            end

            self:Present(true);
       end
    end);
end

---加载完view后的回调
function ShopUICtrl:OnViewLoad()
    self:Init();
end

---只执行一次的内容
function ShopUICtrl:Init()

end

---可反复重置的内容，比如：切换账号回到登录页面再进来
function ShopUICtrl:Reset()

end

function ShopUICtrl:OnPreShow()
    ShopUIView.RefreshUserMoney();
end

--每次进商店都重新从服务器拉取数据，因为可能数据表已经被更新了
function ShopUICtrl:RefreshShopData()
    HttpNetworkManager.GetShopData(function (rawData)
        local data = cjson.decode(rawData);
        if (tonumber(data.code) == NetworkConst.CODE_OK) then
            self.shopData[ShopTab.Daily] = data.dailyShop;
            self.shopData[ShopTab.Recharge] = data.rechargeShop;
            self.shopData[ShopTab.Hot] = data.hotShop;
            self.shopData[ShopTab.Discount] = data.discountShop;

            ShopUIView.Instance():SWitchTab(ShopUIView.Instance().currentTab);
        end
    end);
end

function ShopUICtrl.TabDailyOnClick()
    ShopUIView.Instance():SWitchTab(ShopTab.Daily);
end

function ShopUICtrl.TabRechargeOnClick()
    ShopUIView.Instance():SWitchTab(ShopTab.Recharge);
end

function ShopUICtrl.TabHotOnClick()
    ShopUIView.Instance():SWitchTab(ShopTab.Hot);
end

function ShopUICtrl.TabDiscountOnClick()
    ShopUIView.Instance():SWitchTab(ShopTab.Discount);
end

function ShopUICtrl.CloseOnClick()
    MainUICtrl.Instance():ShowLobbyUI();
end

function ShopUICtrl.ItemPopupButtonBuyEventOnClick()
    ShopUIView.Instance().popedShopItem:RealBuyOnClick();
    ShopUICtrl.ItemPopupCloseOnClick();
end

function ShopUICtrl.ItemPopupCloseOnClick()
    ShopUIView.Instance().shopItemPopup:SetActive(false);
end
